    x = np_array_ops.array([[0, 1], [1, 1]])
    self.assertAllEqual(
        np_math_ops.count_nonzero(x, axis=0, keepdims=True), [[1, 2]]
    )
    self.assertAllEqual(
        np_math_ops.count_nonzero(x, axis=-1, keepdims=True), [[1], [2]]
    )
    self.assertAllEqual(np_math_ops.count_nonzero(x, keepdims=True), [[3]])
    self.assertAllEqual(
